import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.DbSlGjul.js";const m=JSON.parse('{"title":"Add a new attachment","description":"","frontmatter":{},"headers":[],"relativePath":"guides/new-attachment.md","filePath":"guides/new-attachment.md","lastUpdated":1788882780000}'),l={name:"guides/new-attachment.md"};function r(o,e,s,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="add-a-new-attachment" tabindex="-1">Add a new attachment <a class="header-anchor" href="#add-a-new-attachment" aria-label="Permalink to &quot;Add a new attachment&quot;">​</a></h1><p>An attachment is part of the benchmark only when its physical geometry, simulation model, task definition, and evaluation metadata agree.</p><p>For the <a href="/hivedocs/contribute/">ADL and bimanual open calls</a>, contact the authors before starting the design. Read the <a href="/hivedocs/contribute/requirements">submission requirements and credit policy</a> alongside this technical guide.</p><h2 id="_1-reuse-the-mounting-interface" tabindex="-1">1. Reuse the mounting interface <a class="header-anchor" href="#_1-reuse-the-mounting-interface" aria-label="Permalink to &quot;1. Reuse the mounting interface&quot;">​</a></h2><p>Start from the existing press-fit geometry in the CAD repository. Do not redraw the interface from measurements when an editable source is available.</p><p>The attachment should:</p><ul><li>seat fully in a standard honeycomb cell;</li><li>resist the expected manipulation load;</li><li>remain removable without damaging the base;</li><li>avoid interfering with neighboring cells; and</li><li>preserve a repeatable initial state.</li></ul><p>For an attachment wider than one cell, document exactly which adjacent cells must remain free.</p><h2 id="_2-define-the-task" tabindex="-1">2. Define the task <a class="header-anchor" href="#_2-define-the-task" aria-label="Permalink to &quot;2. Define the task&quot;">​</a></h2><p>Write the task definition before producing the final model:</p><ul><li>initial state;</li><li>required manipulation sequence;</li><li>observable success state;</li><li>timeout;</li><li>number and names of intermediate stages, if any;</li><li>permitted reset procedure; and</li><li>likely failure modes.</li></ul><p>A success condition must be measurable across different platforms without requiring access to internal robot state.</p><h2 id="_3-produce-the-physical-files" tabindex="-1">3. Produce the physical files <a class="header-anchor" href="#_3-produce-the-physical-files" aria-label="Permalink to &quot;3. Produce the physical files&quot;">​</a></h2><p>Provide:</p><ul><li>editable CAD source;</li><li>STL files with descriptive names;</li><li>a complete bill of printed components;</li><li>print orientation and support requirements;</li><li>assembly instructions; and</li><li>a photograph or render of the assembled mechanism.</li></ul><p>If the mechanism requires non-printed hardware, list the exact specification and a generally available alternative.</p><h2 id="_4-produce-the-articulated-model" tabindex="-1">4. Produce the articulated model <a class="header-anchor" href="#_4-produce-the-articulated-model" aria-label="Permalink to &quot;4. Produce the articulated model&quot;">​</a></h2><p>The simulation asset should include:</p><ul><li>visual and collision geometry;</li><li>named joints and links;</li><li>joint axes, limits, and initial values;</li><li>mass and inertia values with their derivation;</li><li>contact and friction assumptions; and</li><li>a smoke test that drives the mechanism through its full range.</li></ul><p>Keep identified parameters separate from nominal defaults when they depend on a particular printed instance.</p><h2 id="_5-extend-the-protocol" tabindex="-1">5. Extend the protocol <a class="header-anchor" href="#_5-extend-the-protocol" aria-label="Permalink to &quot;5. Extend the protocol&quot;">​</a></h2><p>Propose a stable lowercase <code>attachment_id</code> and supply the task metadata for review. Once the attachment is accepted into a versioned benchmark extension, coordinate the following updates with the maintainers:</p><ul><li>the module reference;</li><li>the success and timeout table;</li><li>stage numbering, if applicable;</li><li><code>trials.csv</code> and <code>trials.xlsx</code>;</li><li>logging validation; and</li><li>the reproducibility checklist.</li></ul><p>The current benchmark still requires all 13 conditions, with five trials each. A proposed attachment does not replace an existing condition or change the current runner&#39;s required trial count.</p><h2 id="_6-submit-the-contribution" tabindex="-1">6. Submit the contribution <a class="header-anchor" href="#_6-submit-the-contribution" aria-label="Permalink to &quot;6. Submit the contribution&quot;">​</a></h2><p>Include physical and simulation evidence in the pull request:</p><ul><li>assembled-module image;</li><li>manual actuation through the full range;</li><li>successful fit in the HiveBoard base;</li><li>simulation load test; and</li><li>one completed example trial row.</li></ul>',27)])])}const p=t(l,[["render",r]]);export{m as __pageData,p as default};
